            ${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
          <span className="text-xs font-black text-emerald-500 mt-1">
            +$420.00 (24h)
          </span>
        </div>
      </div>
    );
  }
  return null;
};

const BalanceChart: React.FC = () => {
  // Generate volatile data to simulate real crypto market movement
  const chartData = useMemo(() => {
    const data = [];
    let value = 1105000; // Start slightly lower than current
    const points = 80; // More points for granularity
    const now = new Date();

    for (let i = 0; i < points; i++) {
      // Create sharp peaks and dips
      const volatility = (Math.random() - 0.45) * 12000; 
      // Add trend
      const trend = (i / points) * 20000;

      value = value + volatility + (i % 5 === 0 ? trend / 2 : 0);

      // Ensure we end exactly at the dashboard value for consistency
      if (i === points - 1) value = 1138782.92;

      // Simple mock date logic
      const date = new Date(now.getTime() - (points - i) * 3600000); // Hourly points
      const dateStr = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const timeStr = date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

      data.push({
        fullDate: `${dateStr}, ${timeStr}`,
        value: value
      });
    }
    return data;
  }, []);

  return (
    <ResponsiveContainer width="100%" height="100%">
      <AreaChart data={chartData} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
        <defs>
          <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#34d399" stopOpacity={0.25}/>
            <stop offset="70%" stopColor="#34d399" stopOpacity={0}/>
          </linearGradient>
        </defs>

        {/* Subtle Grid */}
        <CartesianGrid vertical={false} stroke="#27272a" strokeDasharray="3 3" opacity={0.5} />

        <XAxis 
          dataKey="fullDate" 
          hide
        />

        <YAxis 
          hide 
          domain={['dataMin - 10000', 'dataMax + 10000']} // Add padding for aesthetics
        />

        <Tooltip 
          content={<CustomTooltip />} 
          cursor={{ stroke: '#52525b', strokeWidth: 1.5, strokeDasharray: '4 4' }} 
          animationDuration={200}
        />

        {/* The Volatile Chart Line */}
        <Area 
          type="monotone" 
          dataKey="value" 
          stroke="#34d399" // emerald-400
          strokeWidth={2.5}
          fill="url(#chartGradient)" 
          animationDuration={2000}
          activeDot={{ r: 6, fill: '#10b981', stroke: '#fff', strokeWidth: 2 }}
        />
      </AreaChart>
    </ResponsiveContainer>
  );
};

