                    signalStyle = 'bg-orange-500/10 text-orange-500 border-orange-500/20';
                    signalIcon = <AlertTriangle size={10} />;
                    tooltipText = "Inefficient Capital: Deploy to Aave V3 for ~4.2% risk-free APY.";
