                      <div>
                        <div className="text-sm font-bold text-white leading-none mb-1.5">{asset.name}</div>
                        <div className="text-[9px] text-zinc-500 uppercase font-black tracking-widest bg-zinc-800/50 px-1.5 py-0.5 rounded w-fit">{asset.symbol}</div>
                      </div>
                    </td>

                    {/* 2. PRICE (24h) */}
                    <td className="py-6 text-right">
                      <div className="text-sm font-mono font-bold text-zinc-300">
                         {formatCurrency(asset.currentPrice, asset.currentPrice < 1 ? 6 : 2)}
                      </div>
                      <div className={`text-[10px] font-bold mt-1 ${asset.changePercent >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                         {asset.changePercent >= 0 ? '+' : ''}{asset.changePercent}%
                      </div>
                    </td>

                    {/* 3. AVG BUY (Weighted) */}
                    <td className="py-6 text-right">
                       <div className="text-xs font-mono font-medium text-zinc-500">
                          {formatCurrency(asset.avgPurchasePrice, asset.avgPurchasePrice < 1 ? 6 : 2)}
                       </div>
                    </td>

                    {/* 4. HOLDINGS */}
                    <td className="py-6 text-right">
                       <div className="text-xs font-mono font-bold text-zinc-300">
                         {formatQuantity(asset.quantity)}
                       </div>
                    </td>

                    {/* 5. ALLOCATION */}
                    <td className="py-6 text-right">
                       <div className="flex flex-col items-end gap-1.5">
                          <span className="text-xs font-mono font-bold text-white">{allocation.toFixed(1)}%</span>
                          <div className="w-16 h-1 bg-zinc-800 rounded-full overflow-hidden">
                             <div className="h-full bg-zinc-400" style={{ width: `${allocation}%` }}></div>
                          </div>
                       </div>
                    </td>

                    {/* 6. VALUE */}
                    <td className="py-6 text-right">
                      <div className="text-sm font-mono font-black text-white">
                        {formatCurrency(asset.value)}
                      </div>
                    </td>

                    {/* 7. UNREALIZED PNL (Double Line) */}
                    <td className="py-6 text-right">
                        <div className={`text-sm font-mono font-bold ${isPositive ? 'text-emerald-500' : 'text-rose-500'}`}>
                            {isPositive ? '+' : ''}{formatCurrency(pnlValue, 0)}
                        </div>
                        <div className={`text-[10px] font-black mt-1 ${isPositive ? 'text-emerald-500/60' : 'text-rose-500/60'}`}>
                            ({isPositive ? '+' : ''}{pnlPercent.toFixed(1)}%)
                        </div>
                    </td>

                    {/* 8. SIGNAL (Context Aware) */}
                    <td className="py-6 text-center group/signal relative">
                      <div className={`inline-flex items-center space-x-2 px-3 py-1.5 rounded-lg border text-[9px] font-black uppercase tracking-wider transition-all cursor-help hover:scale-105 ${signalStyle}`}>
                         {signalIcon}
                         <span>{signalLabel}</span>
                      </div>

                      {/* Tooltip */}
                      <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-full mb-2 w-64 bg-zinc-900 border border-white/10 p-4 rounded-xl opacity-0 group-hover/signal:opacity-100 transition-all pointer-events-none z-50 shadow-[0_10px_40px_-10px_rgba(0,0,0,0.8)] scale-95 group-hover/signal:scale-100 backdrop-blur-xl">
                        <div className="flex items-center space-x-2 mb-2">
                           <Sparkles size={12} className={asset.symbol === 'USDC' ? 'text-orange-500' : 'text-emerald-500'} />
                           <span className="text-[9px] font-black uppercase tracking-widest text-zinc-400">AI Recommendation</span>
                        </div>
                        <p className="text-[10px] text-zinc-300 font-medium leading-relaxed">
                          {tooltipText}
                        </p>
                      </div>
                    </td>

                    {/* 9. ACTIONS (Grouped) */}
                    <td className="py-6 text-right pr-4">
                       <div className="flex items-center justify-end gap-2 opacity-60 group-hover:opacity-100 transition-opacity">

                          <button 
                             className="p-2 rounded-lg bg-zinc-800 border border-white/5 text-zinc-400 hover:text-white hover:bg-zinc-700 transition-colors"
                             title="Rebalance Allocation"
                          >
                             <Scale size={14} />
                          </button>

                          <button 
                             className="p-2 rounded-lg bg-zinc-800 border border-white/5 text-zinc-400 hover:text-rose-400 hover:bg-rose-500/10 transition-colors"
                             title="Hedge Position"
                          >
                             <Shield size={14} />
                          </button>

                          <button 
                             onClick={onTradeClick} 
                             className="flex items-center space-x-2 bg-transparent text-zinc-500 hover:text-white px-2 py-2 rounded-lg transition-all group/btn"
                          >
                            <span className="text-[10px] font-bold uppercase tracking-wider">Manage</span>
                            <ChevronRight size={12} className="group-hover/btn:translate-x-0.5 transition-transform" />
                          </button>

                       </div>
                    </td>

                  </tr>
                );
            })}
          </tbody>
        </table>

        {/* FOOTER: ACTIONS */}
        <div className="pt-8 mt-4 border-t border-white/[0.05] flex items-center justify-center gap-4">

           {/* Export Report (New) */}
           <button className="flex items-center space-x-3 bg-zinc-800 px-6 py-3 rounded-xl text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em] hover:bg-zinc-700 hover:text-white transition-all border border-white/5 hover:border-white/10 active:scale-95">
             <Download size={14} />
             <span>Export Report</span>
           </button>

           <button className="flex items-center space-x-3 bg-white/5 px-8 py-3 rounded-xl text-[10px] font-black text-zinc-300 uppercase tracking-[0.2em] hover:bg-white/10 hover:text-white transition-all border border-white/5 hover:border-white/10 active:scale-95">
             <Wallet size={14} />
             <span>View All Assets</span>
