                         </div>
                         <div className="text-[9px] text-zinc-500">
                             ~1 tx every {(algoDuration * 60 / simulation.numTranches).toFixed(0)} mins
                         </div>
                     </div>
                  </div>

                  {/* STEALTH TOGGLE */}
