const ExecutionView: React.FC = () => {
  // --- STATE ---
  const [payAmount, setPayAmount] = useState('0.00');
  const [tradeMode, setTradeMode] = useState<'market' | 'limit' | 'algo'>('market');
  const [selectedAsset] = useState('ETH'); 

  // Limit Specific State
  const [limitPrice, setLimitPrice] = useState('3150.00');
  const [expiry, setExpiry] = useState('24h');
  const [postOnly, setPostOnly] = useState(false);

  // Algo Specific State
  const [algoDuration, setAlgoDuration] = useState(4);
  const [algoStrategy, setAlgoStrategy] = useState<'TWAP' | 'VWAP' | 'ICEBERG'>('TWAP');
  const [isStealth, setIsStealth] = useState(true);
  const [isAlgoRunning, setIsAlgoRunning] = useState(false);
  const [executionProgress, setExecutionProgress] = useState(0);

  // --- CONSTANTS ---
  const ETH_PRICE = 3208.93;
  const ETH_BALANCE = 350.0000; // Whale balance
  const TOP_10_ASSETS = ['ETH', 'BTC', 'SOL', 'USDC'];
  const BASE_GAS_COST_USD = 4.50; // Cost per transaction
  const ALGO_TRANCHE_SIZE_LIMIT = 50000; // Max size per tranche to avoid impact

  const USDC_ICON = 'https://cryptologos.cc/logos/usd-coin-usdc-logo.png?v=035';
  const ETH_ICON = 'https://cryptologos.cc/logos/ethereum-eth-logo.png?v=035';

  // --- CORE ENGINE CALCULATIONS ---

  const simulation = useMemo(() => {
    const pay = parseFloat(payAmount) || 0;
    const usdValue = pay * ETH_PRICE;
    const limitP = parseFloat(limitPrice) || ETH_PRICE;

    // 1. REALISTIC PRICE IMPACT SIMULATION (For Swap)
    let impactPct = 0;
    if (usdValue > 5_000_000) impactPct = 1.2;      
    else if (usdValue > 1_000_000) impactPct = 0.4; 
    else if (usdValue > 100_000) impactPct = 0.05;  
    else impactPct = 0.01;                          

    const impactCost = usdValue * (impactPct / 100);

    // 2. LIMIT ORDER CALCULATIONS
    const distanceToMarket = ((limitP - ETH_PRICE) / ETH_PRICE) * 100;
    const isAboveMarket = distanceToMarket > 0; // Buying above market?

    // Probability Logic
    let execProbability = 0;
    let probLabel = 'LOW';
    let probColor = 'text-zinc-500';
    let probMessage = '';

    if (isAboveMarket) {
        execProbability = 100;
        probLabel = 'IMMEDIATE';
        probColor = 'text-orange-500';
        probMessage = "Order price is above market. Will execute immediately as Taker.";
    } else if (Math.abs(distanceToMarket) < 1.5) {
        execProbability = 85;
        probLabel = 'HIGH';
        probColor = 'text-emerald-500';
        probMessage = "Price touched this level 3 times in the last 24h. High probability fill.";
    } else if (Math.abs(distanceToMarket) < 5) {
        execProbability = 45;
        probLabel = 'MODERATE';
        probColor = 'text-amber-500';
        probMessage = "Requires market correction. Good accumulation zone.";
    } else {
        execProbability = 12;
        probLabel = 'LOW';
        probColor = 'text-rose-500';
        probMessage = "Deep discount. Low probability of fill in next 24h.";
    }

    // 3. LIQUIDITY & SAFETY SCORE LOGIC (Legacy / Swap)
    let safetyScore = 0;
    let liquidityLabel = '';
    let liquidityColor = '';
    let liquidityMessage = '';

    if (tradeMode === 'algo') {
        safetyScore = 9.9;
        liquidityLabel = 'ALGO OPTIMIZED';
        liquidityColor = 'text-purple-400';
        liquidityMessage = "Stealth execution enabled. Orders distributed to eliminate front-running.";
    } else {
        if (TOP_10_ASSETS.includes(selectedAsset) && usdValue < 1_000_000) {
            safetyScore = 9.9;
            liquidityLabel = 'OPTIMAL LIQUIDITY';
            liquidityColor = 'text-emerald-500';
            liquidityMessage = "Deep Liquidity detected. Price impact is negligible.";
        } else if (impactPct > 1) {
            safetyScore = 4.5;
            liquidityLabel = 'LOW LIQUIDITY';
            liquidityColor = 'text-rose-500';
            liquidityMessage = "Critical slippage risk. Algo execution recommended.";
        } else {
            safetyScore = 7.8;
            liquidityLabel = 'MODERATE';
            liquidityColor = 'text-amber-500';
            liquidityMessage = "Slight slippage expected. Consider limit orders.";
        }
    }

    // 4. ALGO METRICS
    const numTranches = Math.max(algoDuration * 3, Math.ceil(usdValue / ALGO_TRANCHE_SIZE_LIMIT));
    const algoTotalGas = numTranches * BASE_GAS_COST_USD;
    const swapTotalGas = BASE_GAS_COST_USD * 1.5; 

    // 5. RECEIVE AMOUNT LOGIC
    let finalReceive = '0.00';
    if (tradeMode === 'limit') {
        finalReceive = (pay * limitP).toFixed(2);
    } else {
        finalReceive = (usdValue * (1 - impactPct/100)).toFixed(2);
    }

    return {
        usdValue,
        receiveAmount: finalReceive,
        impactPct,
        impactCost,
        safetyScore,
        liquidityLabel,
        liquidityColor,
        liquidityMessage,
        numTranches,
        algoTotalGas,
        swapTotalGas,
        distanceToMarket,
        execProbability,
        probLabel,
        probColor,
        probMessage,
        potentialSavings: impactCost - (algoTotalGas - swapTotalGas),
        recommendAlgo: (impactCost - (algoTotalGas - swapTotalGas)) > 50
    };
  }, [payAmount, tradeMode, selectedAsset, algoDuration, limitPrice]);


  // --- HANDLERS ---
  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val === '' || /^\d*\.?\d*$/.test(val)) {
      setPayAmount(val);
    }
  };

  const handleMaxClick = () => {
    const max = Math.max(0, ETH_BALANCE - 0.004); // Minus gas
    setPayAmount(max.toFixed(4));
  };

  const adjustLimitPrice = (pct: number) => {
      const newPrice = pct === 0 ? ETH_PRICE : ETH_PRICE * (1 + pct / 100);
      setLimitPrice(newPrice.toFixed(2));
  };

  // Simulation of Algo Progress
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isAlgoRunning && executionProgress < 100) {
      interval = setInterval(() => {
        setExecutionProgress(prev => Math.min(prev + 0.5, 100));
      }, 100);
    }
    return () => clearInterval(interval);
  }, [isAlgoRunning, executionProgress]);


  // --- VISUALIZATION DATA ---
  const sparklineData = useMemo(() => [
    { v: 3100 }, { v: 3140 }, { v: 3120 }, { v: 3180 }, 
    { v: 3160 }, { v: 3220 }, { v: 3190 }, { v: 3250 },
    { v: 3230 }, { v: 3208.93 }
  ], []);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-10 gap-8 items-start h-full animate-in fade-in slide-in-from-bottom-4 duration-700">

      {/* ---------------------------------------------------------------------------
          LEFT PANEL: ENGINE & INPUT
      --------------------------------------------------------------------------- */}
      <section className="lg:col-span-4 flex flex-col h-full" aria-labelledby="engine-title">
        <div className="bg-zinc-900/40 border border-white/5 rounded-[2.5rem] p-8 shadow-2xl backdrop-blur-md relative overflow-hidden flex flex-col h-full">

          {/* TAB SWITCHER */}
          <div className="flex items-center justify-between mb-8 shrink-0">
            <div className="flex items-center space-x-6">
              <button 
                onClick={() => setTradeMode('market')}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 pb-1 ${tradeMode === 'market' ? 'text-white border-emerald-500' : 'text-zinc-500 border-transparent hover:text-zinc-300'}`}
              >
                Swap
              </button>

              <button 
                onClick={() => setTradeMode('limit')}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 pb-1 ${tradeMode === 'limit' ? 'text-blue-400 border-blue-500' : 'text-zinc-500 border-transparent hover:text-zinc-300'}`}
              >
                Limit
              </button>

              {/* ALGO TAB with SMART BADGE */}
              <button 
                onClick={() => setTradeMode('algo')}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 pb-1 flex items-center gap-2 relative ${tradeMode === 'algo' ? 'text-purple-400 border-purple-500' : 'text-zinc-500 border-transparent hover:text-zinc-300'}`}
              >
                <Ghost size={12} /> Algo
                {/* Cross-Sell Badge */}
                {tradeMode !== 'algo' && simulation.recommendAlgo && (
                    <span className="absolute -top-3 -right-16 flex items-center gap-1 bg-purple-500 text-white text-[9px] px-1.5 py-0.5 rounded-full animate-pulse shadow-[0_0_10px_rgba(168,85,247,0.5)]">
                        <Flame size={8} fill="currentColor" /> SAVE ~${simulation.potentialSavings.toFixed(0)}
                    </span>
                )}
              </button>
            </div>
            <button className="bg-zinc-800 p-2.5 rounded-xl border border-white/5 text-zinc-400 hover:text-white cursor-pointer transition-colors outline-none">
              <Settings size={18} aria-hidden="true" />
            </button>
          </div>

          {/* ACTIVE ALGO MONITORING */}
          {tradeMode === 'algo' && isAlgoRunning ? (
             <div className="space-y-6 py-4 animate-in fade-in zoom-in-95 duration-500 flex-1 flex flex-col">
                <div className="flex items-center justify-between">
                   <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                     <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                     Execution Active
                   </span>
                   <span className="text-[10px] font-mono font-bold text-purple-400">{algoStrategy} • {algoDuration}H</span>
