  // --- CONSTANTS ---
  const ETH_PRICE = 3208.93;
  const ETH_BALANCE = 350.0000; // Whale balance
  const BASE_GAS_COST_USD = 9.75; // B2B Pivot spec
  const MIN_TRANCHE_USD = 2000; // Minimum viable tranche size

  // V3.1 Constants
  const SUPPORT_LEVEL = 3180.00; // Adjusted for visual gap logic
  const RESISTANCE_LEVEL = 3280.00;
  const RISK_FREE_RATE = 0.042; // 4.2% APY (Aave/Compound)

  const USDC_ICON = 'https://cryptologos.cc/logos/usd-coin-usdc-logo.png?v=035';
  const ETH_ICON = 'https://cryptologos.cc/logos/ethereum-eth-logo.png?v=035';

  // --- CORE ENGINE CALCULATIONS ---

  const simulation = useMemo(() => {
    const pay = parseFloat(payAmount) || 0;
    const usdValue = pay * ETH_PRICE; // Value at Market
    const limitP = parseFloat(limitPrice) || ETH_PRICE;
    const limitValue = pay * limitP; // Value at Limit

    // 1. SWAP IMPACT SIMULATION
    let swapImpactPct = 0;
    if (usdValue > 0) {
        swapImpactPct = Math.min(Math.pow(usdValue / 1_000_000, 1.2) * 0.45, 15);
    }
    const swapImpactCost = usdValue * (swapImpactPct / 100);

    // 2. ALGO TRANCHING LOGIC
    const maxViableTranches = Math.floor(usdValue / MIN_TRANCHE_USD);
    const totalMinutes = algoDuration * 60;
    let optimalTranches = Math.floor(totalMinutes / 20); 
    if (optimalTranches > maxViableTranches) optimalTranches = Math.max(1, maxViableTranches);
    if (optimalTranches < 1) optimalTranches = 1;
    if (usdValue === 0) optimalTranches = 0;

    const trancheSizeETH = optimalTranches > 0 ? pay / optimalTranches : 0;
    const avgIntervalMins = optimalTranches > 0 ? Math.floor(totalMinutes / optimalTranches) : 0;
    const algoTrancheImpactPct = Math.min(Math.pow((usdValue/optimalTranches) / 1_000_000, 1.2) * 0.45, 15);
    const algoTotalImpactCost = usdValue * (algoTrancheImpactPct / 100);
    const algoTotalGas = optimalTranches * BASE_GAS_COST_USD;
    const swapTotalGas = BASE_GAS_COST_USD; // Single tx

    // Savings Calculation
    const totalSwapCost = swapImpactCost + swapTotalGas;
    const totalAlgoCost = algoTotalImpactCost + algoTotalGas;
    const netSavings = totalSwapCost - totalAlgoCost;
    const isAlgoEfficient = netSavings > 0;

    // 3. MARKET INTELLIGENCE (V5.0 EXECUTION INTELLIGENCE)
    const routingScore = 9.9;
    const liquidityBuffer = '18x';
    const routeSplit = [
        { dex: 'Uniswap V3', pct: 65, color: 'bg-pink-500' },
        { dex: 'Curve', pct: 25, color: 'bg-blue-500' },
        { dex: 'SushiSwap', pct: 10, color: 'bg-purple-500' }
    ];

    // 4. LIMIT INTELLIGENCE (V3.1)
    const distanceToMarket = ((limitP - ETH_PRICE) / ETH_PRICE) * 100;
    const isAboveMarket = distanceToMarket > 0;

    // Probability & Timing
    let execProbability = 0;
    let probLabel = 'LOW';
    let probColor = 'text-zinc-500';
    let timeHorizon = '> 4 Days';
    let timeRange = '3d - 7d';

    if (isAboveMarket) {
        execProbability = 100;
        probLabel = 'IMMEDIATE';
        probColor = 'text-orange-500';
        timeHorizon = 'Instant';
        timeRange = 'Now';
    } else {
        const absDist = Math.abs(distanceToMarket);
        if (absDist < 0.5) {
            execProbability = 92;
            probLabel = 'VERY HIGH';
            probColor = 'text-emerald-400';
            timeHorizon = '< 1 Hour';
            timeRange = '10m - 90m';
        } else if (absDist < 1.5) {
            execProbability = 75;
            probLabel = 'HIGH';
            probColor = 'text-emerald-500';
            timeHorizon = '~12 Hours';
            timeRange = '4h - 24h';
        } else if (absDist < 3.0) {
            execProbability = 45;
            probLabel = 'MEDIUM';
            probColor = 'text-amber-500';
            timeHorizon = '~2 Days';
            timeRange = '12h - 4d';
        } else {
            execProbability = 12;
            probLabel = 'LOW';
            probColor = 'text-rose-500';
            timeHorizon = '> 4 Days';
            timeRange = '3d - GTC';
        }
    }

    // Capital Drag (Opportunity Cost)
    const dailyYieldLoss = (limitValue * RISK_FREE_RATE) / 365;

    // Walls Ahead (Volume Calculation)
    const wallsAheadUsd = Math.abs(distanceToMarket) * 8_000_000; 

    // Structure Analysis Status
    let structureLabel = 'IN RANGE';
    let structureColor = 'text-zinc-400';
    if (limitP < SUPPORT_LEVEL) {
        structureLabel = 'BELOW SUPPORT';
        structureColor = 'text-emerald-400';
    } else if (limitP > RESISTANCE_LEVEL) {
        structureLabel = 'ABOVE RESISTANCE';
        structureColor = 'text-rose-400';
    } else if (limitP < ETH_PRICE && limitP > SUPPORT_LEVEL) {
        structureLabel = 'NO MAN\'S LAND';
        structureColor = 'text-amber-500';
    }

    // 5. CHART DATA (Schedule)
    const scheduleData = [];
    if (optimalTranches > 0) {
        let currentTime = new Date();
        for (let i = 0; i < optimalTranches; i++) {
             let variance = 1;
             if (algoRandomize) variance = 0.8 + Math.random() * 0.4; 
             scheduleData.push({
                 id: i,
                 time: currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                 volume: trancheSizeETH * variance,
                 fill: '#8b5cf6'
             });
             currentTime = new Date(currentTime.getTime() + avgIntervalMins * 60000);
        }
    }

    // 6. RECEIVE AMOUNT
    let finalReceive = '0.00';
    if (tradeMode === 'limit') {
        finalReceive = limitValue.toFixed(2); // Strict Math: Amount * Limit Price
    } else if (tradeMode === 'algo') {
        finalReceive = ((usdValue - (algoTotalImpactCost + algoTotalGas))).toFixed(2);
    } else {
        finalReceive = (usdValue * (1 - swapImpactPct/100)).toFixed(2);
    }

    return {
        usdValue,
        limitValue,
        receiveAmount: finalReceive,
        swapImpactPct,
        swapImpactCost,
        algoTrancheImpactPct,
        algoTotalImpactCost,
        numTranches: optimalTranches,
        avgIntervalMins,
        algoTotalGas,
        swapTotalGas,
        netSavings,
        isAlgoEfficient,
        scheduleData,

        // Market V5.0 Metrics
        routingScore,
        liquidityBuffer,
        routeSplit,
        totalSwapCost,

        // Limit Metrics
        distanceToMarket,
        isAboveMarket,
        execProbability,
        probLabel,
        probColor,
        timeHorizon,
        timeRange,
        dailyYieldLoss,
        structureLabel,
        structureColor,
        wallsAheadUsd
    };
  }, [payAmount, tradeMode, selectedAsset, algoDuration, limitPrice, algoRandomize]);


  // --- HANDLERS ---
  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val === '' || /^\d*\.?\d*$/.test(val)) {
      setPayAmount(val);
    }
  };

  const handleMaxClick = () => {
    const max = Math.max(0, ETH_BALANCE - 0.01);
    setPayAmount(max.toFixed(4));
  };

  const adjustLimitPrice = (pct: number) => {
      const newPrice = pct === 0 ? ETH_PRICE : ETH_PRICE * (1 + pct / 100);
      setLimitPrice(newPrice.toFixed(2));
  };

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isAlgoRunning && executionProgress < 100) {
      interval = setInterval(() => {
        setExecutionProgress(prev => Math.min(prev + 0.5, 100));
      }, 100);
    }
    return () => clearInterval(interval);
  }, [isAlgoRunning, executionProgress]);


  // --- VISUALIZATION DATA ---

  // 1. Structure Chart (Limit V3.1)
  const structureData = useMemo(() => {
      const data = [];
      let currentP = 3195; // Start slightly below real market
      // Simulate last 24h price action ending exactly at MARKET PRICE
      for(let i=0; i<=20; i++) {
          if (i === 20) {
             data.push({ i, price: ETH_PRICE }); // Force end at market
          } else {
             currentP = currentP + (Math.random() * 30 - 12);
             data.push({ i, price: currentP });
          }
      }
      return data;
  }, []);

  // 2. Depth Chart Data (Limit V3.1)
  const depthData = useMemo(() => {
      const data = [];
      const limitP = parseFloat(limitPrice) || ETH_PRICE;
      const startPrice = Math.min(limitP, ETH_PRICE) * 0.98;
      const endPrice = Math.max(limitP, ETH_PRICE) * 1.02;

      for(let i = startPrice; i <= endPrice; i+= (endPrice - startPrice)/20) {
          let bidVol = 0;
          let askVol = 0;
          if (i <= ETH_PRICE) {
             bidVol = Math.abs(ETH_PRICE - i) * 500_000 + 100_000;
          }
          if (i >= ETH_PRICE) {
             askVol = Math.abs(i - ETH_PRICE) * 500_000 + 100_000;
          }
          data.push({ price: i, bidVol, askVol });
      }
      return data;
  }, [limitPrice]);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-10 gap-8 items-start h-full animate-in fade-in slide-in-from-bottom-4 duration-700">

      {/* ---------------------------------------------------------------------------
          LEFT PANEL: ENGINE & INPUT
      --------------------------------------------------------------------------- */}
      <section className="lg:col-span-4 flex flex-col h-full" aria-labelledby="engine-title">
        <div className="bg-zinc-900/40 border border-white/5 rounded-[2.5rem] p-8 shadow-2xl backdrop-blur-md relative overflow-hidden flex flex-col h-full">

          {/* TAB SWITCHER */}
          <div className="flex items-center justify-between mb-8 shrink-0">
            <div className="flex items-center space-x-6">
              <button 
                onClick={() => setTradeMode('market')}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 pb-1 ${tradeMode === 'market' ? 'text-white border-emerald-500' : 'text-zinc-500 border-transparent hover:text-zinc-300'}`}
              >
                Swap
              </button>

              <button 
                onClick={() => setTradeMode('limit')}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 pb-1 ${tradeMode === 'limit' ? 'text-blue-400 border-blue-500' : 'text-zinc-500 border-transparent hover:text-zinc-300'}`}
              >
                Limit
              </button>

              {/* ALGO TAB with DYNAMIC SAVINGS BADGE */}
              <button 
                onClick={() => setTradeMode('algo')}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 pb-1 flex items-center gap-2 relative ${tradeMode === 'algo' ? 'text-purple-400 border-purple-500' : 'text-zinc-500 border-transparent hover:text-zinc-300'}`}
              >
                <Ghost size={12} /> Algo
                {/* Cross-Sell Badge Logic */}
                {tradeMode !== 'algo' && simulation.netSavings > 50 && (
                    <div className="absolute -top-3 -right-24 flex items-center gap-1.5 bg-purple-500 text-white text-[9px] px-2 py-0.5 rounded-full animate-pulse shadow-[0_0_10px_rgba(168,85,247,0.5)] z-20 group">
                        <Flame size={8} fill="currentColor" /> 
                        <span className="font-bold whitespace-nowrap">SAVE ${simulation.netSavings.toFixed(0)}</span>
                        {/* Tooltip */}
                        <div className="absolute top-full mt-1 left-1/2 -translate-x-1/2 bg-black border border-white/10 p-2 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity w-32 text-center pointer-events-none">
                           Switch to TWAP to save on slippage.
                        </div>
                    </div>
                )}
              </button>
            </div>
            <button className="bg-zinc-800 p-2.5 rounded-xl border border-white/5 text-zinc-400 hover:text-white cursor-pointer transition-colors outline-none">
              <Settings size={18} aria-hidden="true" />
            </button>
          </div>

          {/* ACTIVE ALGO MONITORING (Overlay) */}
          {tradeMode === 'algo' && isAlgoRunning ? (
             <div className="space-y-6 py-4 animate-in fade-in zoom-in-95 duration-500 flex-1 flex flex-col">
                <div className="flex items-center justify-between">
                   <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                     <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                     Execution Active
                   </span>
                   <span className="text-[10px] font-mono font-bold text-purple-400">{algoStrategy} • {algoDuration}H</span>
                </div>

                <div className="bg-black/40 border border-white/5 rounded-3xl p-6 relative overflow-hidden">
                    <div className="flex justify-between items-end mb-4 relative z-10">
                        <div>
                           <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-1">Filled Amount</p>
                           <p className="text-2xl font-mono font-bold text-white">{((parseFloat(payAmount) || 0) * (executionProgress/100)).toFixed(4)} ETH</p>
                        </div>
                        <div className="text-right">
                           <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-1">Avg Price</p>
                           <p className="text-xl font-mono font-bold text-emerald-500">$3,205.12</p>
                        </div>
                    </div>
                    <div className="h-3 w-full bg-zinc-800 rounded-full overflow-hidden mb-2 relative z-10">
                       <div className="h-full bg-gradient-to-r from-purple-600 to-purple-400 transition-all duration-300" style={{ width: `${executionProgress}%` }}></div>
                    </div>
                    <div className="flex justify-between text-[9px] font-mono text-zinc-500 relative z-10">
                       <span>{executionProgress.toFixed(1)}% Complete</span>
                       <span>~2h 14m Remaining</span>
                    </div>
                </div>

                <div className="mt-auto">
                    <button 
                      onClick={() => setIsAlgoRunning(false)}
                      className="w-full py-4 bg-rose-500/10 text-rose-500 border border-rose-500/20 rounded-[1.5rem] font-black text-[11px] uppercase tracking-[0.25em] hover:bg-rose-500 hover:text-white transition-all flex items-center justify-center gap-2"
                    >
                      <StopCircle size={16} /> Stop Engine
                    </button>
                </div>
             </div>
          ) : (
          <div className="flex-1 flex flex-col space-y-4">

            {/* INPUT BLOCK 1: PAY AMOUNT */}
            <div className={`bg-black/40 border ${tradeMode === 'algo' ? 'border-purple-500/20' : tradeMode === 'limit' ? 'border-blue-500/20' : 'border-white/5'} rounded-[2rem] p-6 focus-within:border-emerald-500/40 transition-all`}>
              <div className="flex justify-between items-center mb-4">
                <label htmlFor="pay-input" className="text-[10px] font-bold text-zinc-500 uppercase tracking-[0.2em]">
                   {tradeMode === 'algo' ? 'TOTAL ORDER SIZE' : 'YOU PAY'}
                </label>
                <button 
                  onClick={() => setPayAmount(ETH_BALANCE.toFixed(4))}
                  className="flex items-center space-x-1 text-[10px] font-bold text-zinc-400 hover:text-white transition-colors"
                >
                  <span>Available:</span>
                  <span className="font-mono text-zinc-300">{ETH_BALANCE.toFixed(4)} ETH</span>
                </button>
              </div>

              <div className="flex justify-between items-center gap-4">
                <input 
                  id="pay-input"
                  type="text" 
                  value={payAmount}
                  onChange={handleAmountChange}
                  placeholder="0.00"
                  className="bg-transparent text-3xl lg:text-4xl font-mono font-bold text-white focus:outline-none w-full tracking-tighter placeholder:text-zinc-800"
                />
                <div className="flex items-center space-x-2">
                  <button 
                    onClick={handleMaxClick}
                    className="text-[9px] font-black text-emerald-500 hover:text-emerald-400 uppercase tracking-widest bg-emerald-500/10 px-2.5 py-2 rounded-lg border border-emerald-500/20 transition-all active:scale-95"
                  >
                    Max
                  </button>
                  <button className="flex items-center space-x-2 bg-zinc-800 border border-white/10 px-3 py-2 rounded-xl hover:bg-zinc-700 transition-all shadow-inner shrink-0 min-w-[100px]">
                    <div className="w-5 h-5 rounded-full bg-indigo-600 flex items-center justify-center border border-white/5 overflow-hidden">
                      <img src={ETH_ICON} alt="ETH" className="w-full h-full object-contain p-0.5" />
                    </div>
                    <span className="text-sm font-bold">ETH</span>
                    <ChevronDown size={14} className="text-zinc-500 ml-auto" />
                  </button>
                </div>
              </div>
            </div>

            {/* CONDITIONAL INPUT: LIMIT PRICE (With Warning) */}
            {tradeMode === 'limit' && (
                <div className={`bg-black/40 border rounded-[2rem] p-6 focus-within:border-blue-500/50 transition-all animate-in slide-in-from-top-2 ${simulation.isAboveMarket ? 'border-orange-500/40' : 'border-blue-500/20'}`}>
                    <div className="flex justify-between items-center mb-4">
                        <label className={`text-[10px] font-bold uppercase tracking-[0.2em] flex items-center gap-2 ${simulation.isAboveMarket ? 'text-orange-500' : 'text-zinc-500'}`}>
                           LIMIT PRICE {simulation.isAboveMarket && <AlertTriangle size={12} className="animate-pulse" />}
                        </label>
                        <div className="flex items-center gap-2">
                           <button onClick={() => adjustLimitPrice(0)} className="text-[9px] font-black text-zinc-400 bg-zinc-800 px-2 py-1 rounded hover:bg-zinc-700 transition-colors uppercase">Market</button>
                           <button onClick={() => adjustLimitPrice(-1)} className="text-[9px] font-black text-zinc-400 bg-zinc-800 px-2 py-1 rounded hover:bg-zinc-700 transition-colors">-1%</button>
                           <button onClick={() => adjustLimitPrice(-5)} className="text-[9px] font-black text-zinc-400 bg-zinc-800 px-2 py-1 rounded hover:bg-zinc-700 transition-colors">-5%</button>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                         <span className={`text-2xl font-bold ${simulation.isAboveMarket ? 'text-orange-500' : 'text-zinc-500'}`}>$</span>
                         <input 
                            type="text"
                            value={limitPrice}
                            onChange={(e) => setLimitPrice(e.target.value)}
                            className={`bg-transparent text-2xl lg:text-3xl font-mono font-bold focus:outline-none w-full tracking-tighter ${simulation.isAboveMarket ? 'text-orange-400' : 'text-blue-400'}`}
                         />
                         <div className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest bg-zinc-800/50 px-3 py-2 rounded-lg border border-white/5">
                            USDC
                         </div>
                    </div>
                    {simulation.isAboveMarket && (
                        <div className="mt-3 text-[9px] font-bold text-orange-500 bg-orange-500/10 px-3 py-1.5 rounded-lg border border-orange-500/20 flex items-center gap-2">
                            <Info size={10} />
                            Price is above market. Order will execute immediately.
                        </div>
                    )}
                </div>
            )}

            {/* CONFIGURATION AREA */}
            {tradeMode === 'algo' ? (
               <div className="space-y-4 animate-in slide-in-from-bottom-2 flex-1">
                  {/* Strategy Tabs */}
                  <div className="grid grid-cols-3 gap-3">
                     {['TWAP', 'VWAP', 'ICEBERG'].map(strat => (
                        <button 
                           key={strat}
                           onClick={() => setAlgoStrategy(strat as any)}
                           className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all ${algoStrategy === strat ? 'bg-purple-500 text-white border-purple-500 shadow-lg shadow-purple-500/20' : 'bg-zinc-800/50 text-zinc-500 border-white/5 hover:bg-zinc-800'}`}
                        >
                           {strat}
                        </button>
                     ))}
                  </div>

                  {/* Duration Slider */}
                  <div className="bg-zinc-900/50 p-5 rounded-[1.5rem] border border-white/5">
                     <div className="flex justify-between items-center mb-4">
                        <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Execution Duration</span>
                        <span className="text-sm font-mono font-bold text-white">{algoDuration} Hours</span>
                     </div>
                     <input 
                        type="range" 
                        min="1" 
                        max="24" 
                        step="0.5"
                        value={algoDuration} 
                        onChange={(e) => setAlgoDuration(parseFloat(e.target.value))}
                        className="w-full h-2 bg-zinc-700 rounded-lg appearance-none cursor-pointer accent-purple-500"
                     />
                     <div className="mt-4 flex items-center justify-between border-t border-white/5 pt-3">
                         <div className="flex items-center gap-1.5 text-[9px] font-bold text-purple-400 uppercase tracking-wide">
                             <Split size={12} />
                             <span>{simulation.numTranches} Tranches</span>
                         </div>
                         <div className="text-[9px] font-mono text-zinc-500">
                             ~1 tx every {simulation.avgIntervalMins} mins
                         </div>
                     </div>
                  </div>

                  {/* Randomize Toggle */}
                  <div 
                     onClick={() => setAlgoRandomize(!algoRandomize)}
                     className={`p-4 rounded-[1.5rem] border cursor-pointer transition-all flex items-center justify-between group ${algoRandomize ? 'bg-purple-500/10 border-purple-500/30' : 'bg-zinc-900/50 border-white/5'}`}
                  >
                     <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-lg ${algoRandomize ? 'bg-purple-500 text-white' : 'bg-zinc-800 text-zinc-500'}`}>
                           <Shuffle size={16} />
                        </div>
                        <div>
                           <p className={`text-[10px] font-black uppercase tracking-widest ${algoRandomize ? 'text-purple-300' : 'text-zinc-500'}`}>Randomize Intervals</p>
                           <p className="text-[10px] text-zinc-500 leading-tight">Vary execution ±20% (Anti-Gaming)</p>
                        </div>
                     </div>
                     <div className={`w-10 h-5 rounded-full relative transition-colors ${algoRandomize ? 'bg-purple-500' : 'bg-zinc-700'}`}>
                        <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all duration-300 ${algoRandomize ? 'left-6' : 'left-1'}`}></div>
                     </div>
                  </div>
               </div>
            ) : tradeMode === 'limit' ? (
                // LIMIT ADVANCED SETTINGS
                <div className="grid grid-cols-2 gap-4 animate-in slide-in-from-bottom-2">
                    {/* Expiry Dropdown */}
                    <div className="bg-black/40 border border-white/5 rounded-2xl p-4 flex flex-col justify-between group focus-within:border-blue-500/30 transition-colors">
                         <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mb-2 flex items-center gap-1.5 group-hover:text-zinc-300 transition-colors">
                            <Clock size={10} /> Expiry
                         </span>
                         <select 
                            value={expiry} 
                            onChange={(e) => setExpiry(e.target.value)}
                            className="bg-transparent text-sm font-bold text-white outline-none cursor-pointer"
                         >
                            <option value="10m">10 Minutes</option>
                            <option value="1h">1 Hour</option>
                            <option value="24h">24 Hours</option>
                            <option value="3d">3 Days</option>
                            <option value="7d">7 Days</option>
                            <option value="GTC">Never (GTC)</option>
                         </select>
                    </div>

                    {/* Post Only Checkbox */}
                    <div 
                       onClick={() => setPostOnly(!postOnly)}
                       className={`bg-black/40 border rounded-2xl p-4 flex flex-col justify-between cursor-pointer transition-colors ${postOnly ? 'border-emerald-500/30 bg-emerald-500/5' : 'border-white/5 hover:bg-zinc-900'}`}
                       title="Guarantees Maker fees. Cancels if crosses spread."
                    >
                         <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mb-2 flex items-center justify-between">
                            <span>Post-Only</span>
                            {postOnly ? <CheckSquare size={12} className="text-emerald-500" /> : <Square size={12} />}
                         </span>
                         <span className={`text-xs font-bold ${postOnly ? 'text-emerald-500' : 'text-zinc-400'}`}>
                             {postOnly ? 'Maker Guaranteed' : 'Standard'}
                         </span>
                    </div>
                </div>
            ) : (
                // SWAP DIRECTION UI
                <div className="flex justify-center -my-6 relative z-10">
                    <button 
