import React, { useMemo } from 'react';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  Line
} from 'recharts';

interface BalanceChartProps {
  benchmarkMode?: 'USD' | 'ETH' | 'BTC';
}

// Helper to format currency or percentage
const formatValue = (val: number, mode: 'USD' | 'ETH' | 'BTC') => {
  if (mode === 'USD') return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(val);
  return `${val.toFixed(2)}%`; // Percentage for benchmarks
};

const formatCompact = (val: number) => 
  new Intl.NumberFormat('en-US', { notation: "compact", compactDisplay: "short", maximumFractionDigits: 1 }).format(val);

// --- 1. RICH TOOLTIP COMPONENT ---
const RichTooltip = ({ active, payload, label, benchmarkMode = 'USD' }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    const portfolioVal = data.value;
    const benchmarkVal = data.benchmarkValue;

    // For USD mode, calculate PnL relative to start
    // For Benchmark mode, values are already percentages
    const isPositive = portfolioVal >= 0; 
    const isBenchmarkPositive = benchmarkVal >= 0;

    return (
      <div className="bg-[#09090b]/95 border border-white/10 p-4 rounded-2xl shadow-[0_20px_50px_-10px_rgba(0,0,0,0.8)] backdrop-blur-xl min-w-[240px] animate-in fade-in zoom-in-95 duration-200">

        {/* Header: Date & Time */}
        <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2 border-b border-white/5 pb-2">
          {data.fullDate}
        </p>

        {/* Portfolio Stats */}
        <div className="mb-3">
          <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">Portfolio</span>
          <div className="text-xl font-mono font-black text-white tracking-tight mt-0.5">
             {formatValue(portfolioVal, benchmarkMode)}
          </div>
        </div>

        {/* Benchmark Stats (If active) */}
        {benchmarkMode !== 'USD' && (
           <div className="mb-4">
             <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Benchmark ({benchmarkMode})</span>
             <div className="text-lg font-mono font-bold text-zinc-400 tracking-tight mt-0.5">
                {benchmarkVal.toFixed(2)}%
             </div>
           </div>
        )}

        {/* Divider */}
        <div className="h-px w-full bg-white/10 mb-3"></div>

        {/* Breakdown List (Only in USD mode for clarity) */}
        {benchmarkMode === 'USD' && (
          <div className="space-y-2.5">
            {data.breakdown.map((asset: any) => (
              <div key={asset.name} className="flex items-center justify-between text-[11px]">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full" style={{ backgroundColor: asset.color }}></div>
                  <span className="font-bold text-zinc-300">{asset.name}</span>
                </div>
                <div className="flex items-center gap-3">
                  <span className="font-mono text-zinc-400">{formatCompact(asset.value)}</span>
                  <span className={`font-mono font-bold w-10 text-right ${asset.change >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {asset.change >= 0 ? '+' : ''}{asset.change.toFixed(1)}%
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }
  return null;
};

const BalanceChart: React.FC<BalanceChartProps> = ({ benchmarkMode = 'USD' }) => {

  // --- 2. DATA GENERATION (1 WEEK TIMEFRAME) ---
  const chartData = useMemo(() => {
    const data = [];
    const now = new Date();
    const daysToShow = 7;
    const pointsPerDay = 4; // 6-hour intervals for smoothness
    const totalPoints = daysToShow * pointsPerDay;

    // Base values for assets to simulate attribution
    let ethPrice = 3100;
    let solPrice = 135;
    let pepePrice = 0.000010;
    let usdcBalance = 2500; // Stable

    const ethQty = 350;
    const solQty = 45;
    const pepeQty = 450000000;

    // Start values for normalization
    let startTotal = 0;
    let startBenchmark = 0;

    for (let i = 0; i <= totalPoints; i++) {
      // Create a date going back in time
      const date = new Date(now.getTime() - ((totalPoints - i) * (24/pointsPerDay) * 60 * 60 * 1000));

      // Simulate random market movements
      // ETH: Moderate volatility
      ethPrice = ethPrice * (1 + (Math.random() - 0.48) * 0.02); 
      // SOL: Higher volatility
      solPrice = solPrice * (1 + (Math.random() - 0.48) * 0.04);
      // PEPE: High volatility
      pepePrice = pepePrice * (1 + (Math.random() - 0.45) * 0.08);

      // Force end values to match Dashboard mock data roughly
      if (i === totalPoints) {
         ethPrice = 3208.93;
         solPrice = 142.50;
         pepePrice = 0.000012;
      }

      const ethVal = ethPrice * ethQty;
      const solVal = solPrice * solQty;
      const pepeVal = pepePrice * pepeQty;
      const total = ethVal + solVal + pepeVal + usdcBalance;

      // Benchmark Logic (Simulating ETH or BTC behavior)
      // ETH tracks closely to portfolio (since portfolio is 98% ETH)
      // BTC diverges slightly
      let benchmarkPrice = ethPrice; 
      if (benchmarkMode === 'BTC') {
         benchmarkPrice = ethPrice * 0.8 + (Math.random() * 500); // Decouple slightly
      }

      if (i === 0) {
          startTotal = total;
          startBenchmark = benchmarkPrice;
      }

      // Individual Asset Performance (mocked for this specific point vs start)
      const breakdown = [
        { name: 'ETH', value: ethVal, change: ((ethPrice - 3100)/3100)*100, color: '#627EEA' },
        { name: 'SOL', value: solVal, change: ((solPrice - 135)/135)*100, color: '#14F195' },
        { name: 'PEPE', value: pepeVal, change: ((pepePrice - 0.000010)/0.000010)*100, color: '#4ADE80' },
        { name: 'USDC', value: usdcBalance, change: 0, color: '#2775CA' }
      ];

      // Value Calculation based on Mode
      let plotValue = total;
      let benchmarkPlotValue = 0;

      if (benchmarkMode !== 'USD') {
          // Calculate percentage change from start
          plotValue = ((total - startTotal) / startTotal) * 100;

          // Benchmark line (Slightly worse performance to show Alpha)
          const rawBenchmarkChange = ((benchmarkPrice - startBenchmark) / startBenchmark) * 100;
          benchmarkPlotValue = rawBenchmarkChange - 1.2; // Hardcode alpha difference visually
      }

      data.push({
        timestamp: date.getTime(),
        shortDate: new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(date),
        fullDate: new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date),
        value: plotValue,
        benchmarkValue: benchmarkPlotValue,
        startValue: startTotal,
        breakdown: breakdown
      });
    }
    return data;
  }, [benchmarkMode]);

  return (
    <ResponsiveContainer width="100%" height="100%">
      <AreaChart data={chartData} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
        <defs>
          <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#34d399" stopOpacity={0.25}/>
            <stop offset="85%" stopColor="#34d399" stopOpacity={0}/>
          </linearGradient>
        </defs>

        {/* Subtle Grid */}
        <CartesianGrid vertical={false} stroke="#27272a" strokeDasharray="3 3" opacity={0.4} />

        <XAxis 
          dataKey="shortDate" 
          axisLine={false}
          tickLine={false}
          tick={{ fill: '#a1a1aa', fontSize: 10, fontWeight: 700, textTransform: 'uppercase' }}
          interval={3} 
          dy={10}
        />

        <YAxis 
          hide 
          domain={['auto', 'auto']} 
        />

        <Tooltip 
          content={<RichTooltip benchmarkMode={benchmarkMode} />} 
          cursor={{ stroke: '#10b981', strokeWidth: 1.5, strokeDasharray: '4 4' }} 
          animationDuration={200}
        />

        {/* Benchmark Line (Comparison) */}
        {benchmarkMode !== 'USD' && (
            <Line 
                type="monotone"
                dataKey="benchmarkValue"
                stroke="#52525b" // Zinc-600
                strokeWidth={2}
                strokeDasharray="4 4"
                dot={false}
                animationDuration={1500}
            />
        )}

        {/* Main Portfolio Line */}
        <Area 
          type="monotone" 
          dataKey="value" 
          stroke="#34d399" // emerald-400
          strokeWidth={3}
          fill={benchmarkMode === 'USD' ? "url(#chartGradient)" : "none"} 
          animationDuration={1500}
          activeDot={{ 
            r: 6, 
            fill: '#050505', 
            stroke: '#10b981', 
            strokeWidth: 3,
            className: "animate-pulse"
          }}
        />
      </AreaChart>
    </ResponsiveContainer>
  );
};

export default BalanceChart;

