                           <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-1">Avg Price</p>
                           <p className="text-xl font-mono font-bold text-emerald-500">$3,205.12</p>
                        </div>
                    </div>
                    <div className="h-3 w-full bg-zinc-800 rounded-full overflow-hidden mb-2 relative z-10">
                       <div className="h-full bg-gradient-to-r from-purple-600 to-purple-400 transition-all duration-300" style={{ width: `${executionProgress}%` }}></div>
                    </div>
                    <div className="flex justify-between text-[9px] font-mono text-zinc-500 relative z-10">
                       <span>{executionProgress.toFixed(1)}% Complete</span>
                       <span>~2h 14m Remaining</span>
                    </div>
                </div>

                <div className="mt-auto">
                    <button 
                      onClick={() => setIsAlgoRunning(false)}
                      className="w-full py-4 bg-rose-500/10 text-rose-500 border border-rose-500/20 rounded-[1.5rem] font-black text-[11px] uppercase tracking-[0.25em] hover:bg-rose-500 hover:text-white transition-all flex items-center justify-center gap-2"
                    >
                      <StopCircle size={16} /> Stop Engine
                    </button>
                </div>
             </div>
          ) : (
          <div className="flex-1 flex flex-col space-y-4">

            {/* INPUT BLOCK 1: PAY AMOUNT */}
            <div className={`bg-black/40 border ${tradeMode === 'algo' ? 'border-purple-500/20' : tradeMode === 'limit' ? 'border-blue-500/20' : 'border-white/5'} rounded-[2rem] p-6 focus-within:border-emerald-500/40 transition-all`}>
              <div className="flex justify-between items-center mb-4">
                <label htmlFor="pay-input" className="text-[10px] font-bold text-zinc-500 uppercase tracking-[0.2em]">
                   {tradeMode === 'algo' ? 'TOTAL ORDER SIZE' : 'YOU PAY'}
                </label>
                <button 
                  onClick={() => setPayAmount(ETH_BALANCE.toFixed(4))}
                  className="flex items-center space-x-1 text-[10px] font-bold text-zinc-400 hover:text-white transition-colors"
                >
                  <span>Available:</span>
                  <span className="font-mono text-zinc-300">{ETH_BALANCE.toFixed(4)} ETH</span>
                </button>
              </div>

              <div className="flex justify-between items-center gap-4">
                <input 
                  id="pay-input"
                  type="text" 
